function generateUpdateBat(e,t){const n=["background.js","content.js","popup.js","popup.html","popup.css","popup-animations.css","manifest.json","config.js","logger.js","utils.js","max.js","shared/constants.js","update-generator.js"];let o="\ufeff@echo off\r\nchcp 65001 >nul\r\n";o+=`set "EXT_FOLDER=${e}"\r\n`,o+=`set "BASE_URL=${t}"\r\n\r\n`,o+="echo Обновление расширения 1C Notification...\r\n\r\n";for(const s of n){const n=s.includes("/")?s.substring(0,s.lastIndexOf("/")):"";n&&(o+=`if not exist "${e}\\${n.replace("/","\\")}" mkdir "${e}\\${n.replace("/","\\")}"\r\n`),o+=`echo Downloading ${s}...\r\n`;const r=`${e}\\${s.replace("/","\\")}`;o+=`powershell -Command "try { Invoke-WebRequest -Uri '${t}${s}' -OutFile '${r}' -ErrorAction Stop; if ((Get-Item '${r}').Length -lt 100) { Remove-Item '${r}'; Write-Host 'FAIL: file too small'; exit 1 }; Write-Host 'OK' } catch { Write-Host ('FAIL: ' + $_.Exception.Message); exit 1 }"\r\n`}return o+="\r\necho.\r\necho Обновление завершено! Перезагрузите расширение в chrome://extensions/\r\npause\r\n",o}window.generateUpdateBat=generateUpdateBat;